#include <Wire.h> 
#include <LiquidCrystal_I2C.h>
// Initialize the I2C LCD. 
// 0x27 is the most common I2C address for these modules. 
// If your screen is blank, try changing 0x27 to 0x3F.
LiquidCrystal_I2C lcd(0x27, 16, 2);
// Define component pins
const int mq135Pin = A0;   // MQ135 Analog output pin
const int buzzerPin = 8;   // Buzzer positive pin
const int ledPin = 9;      // LED anode pin
// Set the threshold for gas detection
const int threshold = 150; 
void setup() {
  // Set pin modes
  pinMode(buzzerPin, OUTPUT);
  pinMode(ledPin, OUTPUT);
  pinMode(mq135Pin, INPUT);
  // Begin Serial monitor for debugging
  Serial.begin(9600);
  // Initialize the I2C LCD and turn on the backlight
  lcd.init();       
  lcd.backlight();
  // Print initial startup message
  lcd.setCursor(0, 0);
  lcd.print(" Gas Detector ");
  lcd.setCursor(0, 1);
  lcd.print(" Warming up... ");
  // Give the sensor a brief moment to warm up
  delay(3000); 
  lcd.clear();
}
void loop() {
  // Read the analog value from the sensor
  int gasValue = analogRead(mq135Pin); 
  // Print data to Serial Monitor (helpful for calibration)
  Serial.print("Gas Level: ");
  Serial.println(gasValue);
  // --- Update LCD Display ---
  // Row 0: Permanent Heading
  lcd.setCursor(0, 0);
  lcd.print(" Gas Detector ");
  // Row 1: Real-time Data
  lcd.setCursor(0, 1);
  lcd.print("Val:");
  lcd.print(gasValue);
  lcd.print("   "); // Extra spaces to clear leftover digits if the value drops
  // --- Trigger Logic ---
  // Check if the current gas level exceeds the safe limit
  if (gasValue > threshold) {
    // Turn ON Buzzer and LED
    digitalWrite(buzzerPin, HIGH);
    digitalWrite(ledPin, HIGH);
    // Display alert status
    lcd.setCursor(9, 1);
    lcd.print("!ALERT!");
  } else {
    // Turn OFF Buzzer and LED
    digitalWrite(buzzerPin, LOW);
    digitalWrite(ledPin, LOW);
    // Display safe status
    lcd.setCursor(9, 1);
    lcd.print(" SAFE  ");
  }
  // Wait half a second before taking the next reading
  delay(500); 
}
